32	import { Hono } from "hono";
33	import { createSetupApp } from "./setup.js";
34	import { bootCloudflare } from "../boot.js";
35	import { SidecarClient } from "../sidecar-client.js";
36	import { CfCompanySkillsService } from "../services/cf-company-skills.js";
37	import { CfAgentInstructionsService } from "../services/cf-agent-instructions.js";
38	import { createHyperdriveDb } from "../db/hyperdrive.js";
39	import { R2Provider } from "../storage/r2-provider.js";
40	import { createCfStorageService } from "../storage/cf-storage-service.js";
41	import { extractRoutesFromRouter } from "../http/express-router-bridge.js";
42	import { resolveActorFromRequest } from "../auth/resolve-actor.js";
43	import { runHeartbeatSweep } from "../cron/heartbeat-sweep.js";
44	import { HttpError } from "../../../server/src/errors.js";
45	import type { RouteDefinition } from "../../../server/src/http/types.js";
46	import type { StorageService } from "../../../server/src/storage/types.js";
47	import type { Db } from "@paperclipai/db";
48	
49	// Server-side route factories
50	import { companyRoutes } from "../../../server/src/routes/companies.js";
51	import { agentRoutes } from "../../../server/src/routes/agents.js";
52	import { assetRoutes } from "../../../server/src/routes/assets.js";
53	import { projectRoutes } from "../../../server/src/routes/projects.js";
54	import { issueRoutes } from "../../../server/src/routes/issues.js";
55	import { issueTreeControlRoutes } from "../../../server/src/routes/issue-tree-control.js";
56	import { routineRoutes } from "../../../server/src/routes/routines.js";
57	import { environmentRoutes } from "../../../server/src/routes/environments.js";
58	import { executionWorkspaceRoutes } from "../../../server/src/routes/execution-workspaces.js";
59	import { goalRoutes } from "../../../server/src/routes/goals.js";
60	import { approvalRoutes } from "../../../server/src/routes/approvals.js";
61	import { secretRoutes } from "../../../server/src/routes/secrets.js";
62	import { costRoutes } from "../../../server/src/routes/costs.js";
63	import { activityRoutes } from "../../../server/src/routes/activity.js";
64	import { dashboardRoutes } from "../../../server/src/routes/dashboard.js";
65	import { userProfileRoutes } from "../../../server/src/routes/user-profiles.js";
66	import { sidebarBadgeRoutes } from "../../../server/src/routes/sidebar-badges.js";
67	import { sidebarPreferenceRoutes } from "../../../server/src/routes/sidebar-preferences.js";
68	import { inboxDismissalRoutes } from "../../../server/src/routes/inbox-dismissals.js";
69	import { instanceSettingsRoutes } from "../../../server/src/routes/instance-settings.js";
70	import { llmRoutes } from "../../../server/src/routes/llms.js";
71	import { authRoutes } from "../../../server/src/routes/auth.js";
72	
73	// ---------------------------------------------------------------------------
74	// Env -- Cloudflare bindings injected at runtime
75	// ---------------------------------------------------------------------------
76	
77	export interface Env {
78	  // Databases
79	  HYPERDRIVE: { connectionString: string };
80	
81	  // Object storage
82	  PAPERCLIP_STORAGE: R2Bucket;
83	
84	  // KV -- setup flags, hot config, session cache
85	  PAPERCLIP_KV: KVNamespace;
86	
87	  // Durable Object namespaces
88	  TASK_DO: DurableObjectNamespace;
89	  AGENT_RUN_DO: DurableObjectNamespace;
90	  SCHEDULER_DO: DurableObjectNamespace;
91	
92	  // Queues
93	  PAPERCLIP_QUEUE: Queue;
94	
95	  // Workflows
96	  HEARTBEAT_WORKFLOW: Workflow;
97	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
98	
99	  // Vars (set in wrangler.toml [vars])
100	  DEPLOYMENT_PLATFORM: string;
101	  DEPLOYMENT_MODE: string;
102	  DEPLOYMENT_EXPOSURE: string;
103	  STORAGE_R2_BUCKET?: string;
104	  STORAGE_R2_PREFIX?: string;
105	
106	  // Sidecar -- the Node server running alongside the Workers deployment.
107	  SIDECAR_URL: string;
108	  SIDECAR_API_KEY: string;
109	}
110	
111	// ---------------------------------------------------------------------------
112	// Per-isolate route cache
113	//
114	// Workers isolates are long-lived within a datacenter edge node. We build the
115	// Express Routers (and extract RouteDefinitions) once per isolate, keyed on
116	// the Hyperdrive connection string (proxy for "same DB config").
117	//
118	// Subsequent requests in the same isolate reuse the cached routes, skipping
119	// the router construction overhead.
120	// ---------------------------------------------------------------------------
121	
122	interface CompiledRoute {
123	  route: RouteDefinition;
124	  re: RegExp;
125	  paramNames: string[];
126	}
127	
128	interface RouteCache {
129	  routes: RouteDefinition[];
130	  compiled: CompiledRoute[];
131	  db: Db;
132	  storage: StorageService;
133	  hyperdriveConnStr: string;
134	}
135	
136	let routeCache: RouteCache | null = null;
137	
138	// Convert an Express-style path pattern (with :param segments) to a RegExp.
139	function pathToRegex(path: string): { re: RegExp; paramNames: string[] } {
140	  const paramNames: string[] = [];
141	  const pattern = path
142	    .replace(/[$()*+.?[\\\]^{|}]/g, "\\$&")
143	    .replace(/:([a-zA-Z_][a-zA-Z0-9_]*)/g, (_match, name: string) => {
144	      paramNames.push(name);
145	      return "([^/]+)";
146	    });
147	  return { re: new RegExp(`^${pattern}$`), paramNames };
148	}
149	
150	function buildRouteCache(env: Env): RouteCache {
151	  const db = createHyperdriveDb(env.HYPERDRIVE);
152	  const r2Provider = new R2Provider(env.PAPERCLIP_STORAGE, {
153	    bucket: env.STORAGE_R2_BUCKET ?? "paperclip-storage",
154	    prefix: env.STORAGE_R2_PREFIX ?? "",
155	  });
156	  const storage = createCfStorageService(r2Provider) as unknown as StorageService;
157	
158	  function ext(router: unknown, prefix: string): RouteDefinition[] {
159	    return extractRoutesFromRouter(router, prefix);
160	  }
161	
162	  const routes: RouteDefinition[] = [
163	    ...ext(companyRoutes(db, storage), "/api/companies"),
164	    ...ext(agentRoutes(db, {}), "/api"),
165	    ...ext(assetRoutes(db, storage), "/api"),
166	    ...ext(projectRoutes(db), "/api"),
167	    ...ext(issueRoutes(db, storage, {}), "/api"),
168	    ...ext(issueTreeControlRoutes(db), "/api"),
169	    ...ext(routineRoutes(db, {}), "/api"),
170	    ...ext(environmentRoutes(db, {}), "/api"),
171	    ...ext(executionWorkspaceRoutes(db), "/api"),
172	    ...ext(goalRoutes(db), "/api"),
173	    ...ext(approvalRoutes(db, {}), "/api"),
174	    ...ext(secretRoutes(db), "/api"),
175	    ...ext(costRoutes(db, {}), "/api"),
176	    ...ext(activityRoutes(db), "/api"),
177	    ...ext(dashboardRoutes(db), "/api"),
178	    ...ext(userProfileRoutes(db), "/api"),
179	    ...ext(sidebarBadgeRoutes(db), "/api"),
180	    ...ext(sidebarPreferenceRoutes(db), "/api"),
181	    ...ext(inboxDismissalRoutes(db), "/api"),
182	    ...ext(instanceSettingsRoutes(db), "/api"),
183	    ...ext(llmRoutes(db), "/api"),
184	    ...ext(authRoutes(db), "/api"),
185	  ];
186	
187	  const compiled: CompiledRoute[] = routes.map((route) => ({
188	    route,
189	    ...pathToRegex(route.path),
190	  }));
191	
192	  return { routes, compiled, db, storage, hyperdriveConnStr: env.HYPERDRIVE.connectionString };
193	}
194	
195	function getRouteCache(env: Env): RouteCache {
196	  if (!routeCache || routeCache.hyperdriveConnStr !== env.HYPERDRIVE.connectionString) {
197	    routeCache = buildRouteCache(env);
198	    console.log(`[CF Worker] Built route cache: ${routeCache.routes.length} routes`);
199	  }
200	  return routeCache;
201	}
202	
203	// ---------------------------------------------------------------------------
204	// Hono app
205	// ---------------------------------------------------------------------------
206	
207	const app = new Hono<{ Bindings: Env }>();
208	
209	// Health check -- always reachable
210	app.get("/api/health", (c) =>
211	  c.json({
212	    status: "ok",
213	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
214	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
215	    ts: new Date().toISOString(),
216	  }),
217	);
218	
219	// First-run setup gate
220	app.use("*", async (c, next) => {
221	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
222	    return next();
223	  }
224	  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
225	  if (setupCompleted !== "true") {
226	    return c.redirect("/setup");
227	  }
228	  return next();
229	});
230	
231	// Setup sub-app
232	app.all("/setup/*", async (c) => {
233	  const setupSub = createSetupApp(c.env);
234	  const url = new URL(c.req.url);
235	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
236	  const rewritten = new Request(url.toString(), c.req.raw);
237	  return setupSub.fetch(rewritten);
238	});
239	
240	app.all("/setup", async (c) => {
241	  const setupSub = createSetupApp(c.env);
242	  const url = new URL(c.req.url);
243	  url.pathname = "/";
244	  const rewritten = new Request(url.toString(), c.req.raw);
245	  return setupSub.fetch(rewritten);
246	});
247	
248	// ---------------------------------------------------------------------------
249	// Main API catch-all -- routes through cached route definitions
250	//
251	// We use a single wildcard handler for /api/* rather than registering one
252	// Hono route per server route definition. This avoids blowing Hono's internal
253	// route trie limit and is simpler to reason about.
254	//
255	// Routing is done manually: iterate the route definitions, match method and
256	// path pattern, and delegate to the handler.
257	// ---------------------------------------------------------------------------
258	
259	function getCompiledRoutes(env: Env) {
260	  const cache = getRouteCache(env);
261	  return { compiled: cache.compiled, db: cache.db, storage: cache.storage };
262	}
263	
264	// R2-native upload endpoints (registered before the catch-all)
265	app.put("/api/assets/:assetId/upload", async (c) => {
266	  const { assets } = await import("@paperclipai/db");
267	  const { eq } = await import("drizzle-orm");
268	  const { forbidden, notFound, badRequest } = await import("../../../server/src/errors.js");
269	
270	  const env = c.env;
271	  const { db } = getRouteCache(env);
272	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
273	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
274	
275	  try {
276	    const assetId = c.req.param("assetId");
277	    if (!assetId) return c.json({ error: "Missing assetId" }, 400);
278	    const assetRow = await db.select().from(assets).where(eq(assets.id, assetId)).then((rows) => rows[0] ?? null);
279	    if (!assetRow) throw notFound("Asset not found");
280	
281	    if (!actor) throw forbidden("Authentication required");
282	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(assetRow.companyId)) {
283	      throw forbidden("No access to this company");
284	    }
285	    if (actor.type === "agent" && actor.companyId !== assetRow.companyId) {
286	      throw forbidden("No access to this company");
287	    }
288	
289	    const body = c.req.raw.body;
290	    if (!body) throw badRequest("Empty request body");
291	    const key = `assets/${assetRow.companyId}/${assetId}`;
292	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
293	    return c.json({ ok: true, key });
294	  } catch (err) {
295	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
296	    console.error("[CF Worker] PUT /api/assets/:assetId/upload", err);
297	    return c.json({ error: "Internal Server Error" }, 500);
298	  }
299	});
300	
301	app.post("/api/issues/:issueId/attachments/upload", async (c) => {
302	  const { issues } = await import("@paperclipai/db");
303	  const { eq } = await import("drizzle-orm");
304	  const { forbidden, notFound, badRequest } = await import("../../../server/src/errors.js");
305	
306	  const env = c.env;
307	  const { db } = getRouteCache(env);
308	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
309	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
310	
311	  try {
312	    const issueId = c.req.param("issueId");
313	    if (!issueId) return c.json({ error: "Missing issueId" }, 400);
314	    const issueRow = await db.select({ id: issues.id, companyId: issues.companyId })
315	      .from(issues).where(eq(issues.id, issueId)).then((rows) => rows[0] ?? null);
316	    if (!issueRow) throw notFound("Issue not found");
317	
318	    if (!actor) throw forbidden("Authentication required");
319	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(issueRow.companyId)) {
320	      throw forbidden("No access to this company");
321	    }
322	    if (actor.type === "agent" && actor.companyId !== issueRow.companyId) {
323	      throw forbidden("No access to this company");
324	    }
325	
326	    const body = c.req.raw.body;
327	    if (!body) throw badRequest("Empty request body");
328	    const filename = (c.req.header("x-filename") ?? "attachment").replace(/[^a-zA-Z0-9._-]/g, "_");
329	    const key = `issues/${issueRow.companyId}/${issueId}/attachments/${filename}`;
330	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
331	    return c.json({ ok: true, key, filename });
332	  } catch (err) {
333	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
334	    console.error("[CF Worker] POST /api/issues/:issueId/attachments/upload", err);
335	    return c.json({ error: "Internal Server Error" }, 500);
336	  }
337	});
338	
339	// Main API catch-all -- manual routing through cached route definitions
340	app.all("/api/*", async (c) => {
341	  const { compiled, db, storage } = getCompiledRoutes(c.env);
342	  const pathname = new URL(c.req.url).pathname;
343	  const method = c.req.method.toUpperCase();
344	
345	  for (const { route, re, paramNames } of compiled) {
346	    if (route.method !== method) continue;
347	    const match = re.exec(pathname);
348	    if (!match) continue;
349	
350	    // Build param map for this match
351	    const params: Record<string, string> = {};
352	    for (let i = 0; i < paramNames.length; i++) {
353	      params[paramNames[i]!] = match[i + 1]!;
354	    }
355	
356	    // Wrap ctx.param to return from our extracted params
357	    const actor = await resolveActorFromRequest(
358	      c.req.raw,
359	      db,
360	      {
361	        deploymentMode: c.env.DEPLOYMENT_MODE === "local_trusted"
362	          ? "local_trusted"
363	          : "authenticated",
364	      },
365	    );
366	
367	    const ctx: import("../../../server/src/http/types.js").RequestCtx = {
368	      method: c.req.method,
369	      url: new URL(c.req.url),
370	      headers: new Headers(c.req.raw.headers),
371	      json<T>(): Promise<T> { return c.req.json<T>(); },
372	      text(): Promise<string> { return c.req.text(); },
373	      param(name: string): string | undefined { return params[name]; },
374	      query(name: string): string | undefined { return c.req.query(name); },
375	      actor,
376	      db,
377	      storage,
378	    };
379	
380	    try {
381	      return await route.handler(ctx);
382	    } catch (err) {
383	      if (err instanceof HttpError) {
384	        return Response.json(
385	          { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
386	          { status: err.status },
387	        );
388	      }
389	      console.error(
390	        `[CF Worker] Unhandled error in ${route.method} ${route.path}: ${
391	          err instanceof Error ? err.stack ?? err.message : String(err)
392	        }`,
393	      );
394	      return Response.json({ error: "Internal Server Error" }, { status: 500 });
395	    }
396	  }
397	
398	  // No route matched
